def solve():
    max_s = 0
    best_params = None

    for n in range(1, 13):
        for p in range(13 + n, 2000):
            # S = (12+n)/p + (13-n)/q < 1
            # (13-n)/q < 1 - (12+n)/p
            # q > (13-n) / (1 - (12+n)/p)
            # q > (13-n)*p / (p - (12+n))

            num = (13 - n) * p
            den = p - (12 + n)

            if den <= 0:
                continue

            q = (num // den) + 1

            if q > 0:
                s = (12 + n) / p + (13 - n) / q
                if s < 1:
                    if s > max_s:
                        max_s = s
                        best_params = (n, p, q)

    return max_s, best_params

max_s, best_params = solve()
print(f"Max S: {max_s}, Params: {best_params}")

